9: import { eval as safeEval } from 'notevil'
10: 
11: import * as challengeUtils from '../lib/challengeUtils'
12: import { challenges } from '../data/datacache'
13: import * as security from '../lib/insecurity'
14: import * as utils from '../lib/utils'
15: 
16: export function b2bOrder () {
17:   return ({ body }: Request, res: Response, next: NextFunction) => {
18:     if (utils.isChallengeEnabled(challenges.rceChallenge) || utils.isChallengeEnabled(challenges.rceOccupyChallenge)) {
19:       const orderLinesData = body.orderLinesData || ''
20:       try {
21:         const sandbox = { safeEval, orderLinesData }
22:         vm.createContext(sandbox)
23:         vm.runInContext('safeEval(orderLinesData)', sandbox, { timeout: 2000 })
24:         res.json({ cid: body.cid, orderNo: uniqueOrderNumber(), paymentDue: dateTwoWeeksFromNow() })
25:       } catch (err) {
26:         if (utils.getErrorMessage(err).match(/Script execution timed out.*/) != null) {
27:           challengeUtils.solveIf(challenges.rceOccupyChallenge, () => { return true })
28:           res.status(503)
29:           next(new Error('Sorry, we are temporarily not available! Please try again later.'))
30:         } else {
31:           challengeUtils.solveIf(challenges.rceChallenge, () => { return utils.getErrorMessage(err) === 'Infinite loop detected - reached max iterations' })
32:           next(err)
33:         }
34:       }
35:     } else {
36:       res.json({ cid: body.cid, orderNo: uniqueOrderNumber(), paymentDue: dateTwoWeeksFromNow() })
37:     }
38:   }
39: 
40:   function uniqueOrderNumber () {
41:     return security.hash(`${(new Date()).toString()}_B2B`)
42:   }
43: 
44:   function dateTwoWeeksFromNow () {
45:     return new Date(new Date().getTime() + (14 * 24 * 60 * 60 * 1000)).toISOString()
46:   }
47: }

